export const LIV_MODULO_COLOR: Record<string, string> = {
  'FISIOLOGÍA': '#3FB984',
  'GLP-1': '#7BB1FF',
  'ACCESO PERÚ': '#E0856B',
  'SÍNTESIS': '#D9BE8A',
  'NUTRICIÓN': '#F5A623',
  'EJERCICIO': '#E5708A',
  'FARMACO+QX': '#8FB6E8',
  'CONDUCTA': '#A78BFA'
};
export const livColor = (m: string) => LIV_MODULO_COLOR[m] || '#9DB07F';
